{
  "name": "Gestão Social - Igreja",
  "description": "Sistema completo para gestão de assistência social em igrejas. Permite cadastro de famílias, registro de visitas, controle de doações (cestas básicas, roupas) e acompanhamento pastoral com dashboards e históricos detalhados."
}

export enum Status {
  Active = 'Active',
  Critical = 'Critical',
  Archived = 'Archived'
}

export enum AidType {
  FoodBasket = 'Cesta Básica',
  Clothes = 'Roupas',
  Medicine = 'Medicamentos',
  Financial = 'Financeiro',
  Spiritual = 'Apoio Espiritual',
  Gas = 'Gás'
}

export interface FamilyMember {
  id: string;
  name: string;
  role: string; // e.g., Pai, Mãe, Filho
  age: number;
  tags?: string[]; // e.g., 'Estuda', 'Desempregado'
  avatarUrl?: string;
}

export interface HistoryRecord {
  id: string;
  date: string;
  type: 'Visit' | 'Aid' | 'Update';
  title: string;
  description: string;
  responsible: string;
}

export interface Family {
  id: string;
  code: string; // e.g., #FAM-2024-001
  name: string; // Family name usually mostly surname or responsible name
  responsibleName: string;
  avatarUrl: string;
  status: Status;
  statusDescription: string;
  address: string;
  phone: string;
  members: FamilyMember[];
  history: HistoryRecord[];
  needs?: string[];
  churchMember: boolean;
  congregation?: string;
}

export interface DashboardStats {
  totalFamilies: number;
  criticalFamilies: number;
  monthlyAid: { name: string; value: number; fill: string }[];
}

import React, { createContext, useContext, useState, ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter, Routes, Route, useLocation, Navigate, useNavigate } from 'react-router-dom';
import { Dashboard } from './pages/Dashboard';
import { Login } from './pages/Login';
import { FamilyList } from './pages/FamilyList';
import { FamilyDetails } from './pages/FamilyDetails';
import { NewFamily } from './pages/NewFamily';
import { NewRecord } from './pages/NewRecord';
import { Family } from './types';
import { MOCK_FAMILIES } from './constants';

// --- Context ---
interface AppContextType {
  families: Family[];
  addFamily: (family: Family) => void;
  isAuthenticated: boolean;
  login: () => void;
  logout: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

const AppProvider = ({ children }: { children: ReactNode }) => {
  const [families, setFamilies] = useState<Family[]>(MOCK_FAMILIES);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);

  const addFamily = (family: Family) => {
    setFamilies(prev => [...prev, family]);
  };

  const login = () => setIsAuthenticated(true);
  const logout = () => setIsAuthenticated(false);

  return (
    <AppContext.Provider value={{ families, addFamily, isAuthenticated, login, logout }}>
      {children}
    </AppContext.Provider>
  );
};

// --- Layout Component ---
const Layout = ({ children }: { children: ReactNode }) => {
  const navigate = useNavigate();
  const location = useLocation();

  const isActive = (path: string) => location.pathname === path;

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark">
      <div className="flex-1 pb-24 md:pb-0 md:pl-64 transition-all duration-300">
        {children}
      </div>

      {/* Desktop Sidebar */}
      <nav className="hidden md:flex flex-col w-64 fixed inset-y-0 left-0 bg-surface-light dark:bg-surface-dark border-r border-gray-200 dark:border-gray-800 z-50">
        <div className="p-6 flex items-center gap-3">
           <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 text-primary">
              <span className="material-symbols-outlined">diversity_3</span>
           </div>
           <h1 className="text-xl font-bold text-slate-800 dark:text-white">Gestão Social</h1>
        </div>
        <div className="flex-1 px-4 space-y-2">
            <SidebarItem icon="dashboard" label="Visão Geral" active={isActive('/dashboard')} onClick={() => navigate('/dashboard')} />
            <SidebarItem icon="groups" label="Famílias" active={isActive('/families')} onClick={() => navigate('/families')} />
            <SidebarItem icon="person_add" label="Novo Cadastro" active={isActive('/new-family')} onClick={() => navigate('/new-family')} />
            <SidebarItem icon="edit_document" label="Atendimento" active={isActive('/new-record')} onClick={() => navigate('/new-record')} />
        </div>
        <div className="p-4 border-t border-gray-200 dark:border-gray-800">
           <SidebarItem icon="logout" label="Sair" active={false} onClick={() => {}} />
        </div>
      </nav>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 w-full bg-surface-light dark:bg-surface-dark border-t border-gray-200 dark:border-gray-800 pb-safe pt-2 px-6 z-50">
        <div className="flex justify-between items-center max-w-lg mx-auto h-16">
          <NavItem icon="dashboard" label="Início" active={isActive('/dashboard')} onClick={() => navigate('/dashboard')} />
          <NavItem icon="diversity_3" label="Famílias" active={isActive('/families')} onClick={() => navigate('/families')} />

          <div className="relative -top-6">
            <button 
              onClick={() => navigate('/new-family')}
              className="size-14 bg-primary text-white rounded-full shadow-lg shadow-primary/30 flex items-center justify-center active:scale-95 transition-transform"
            >
              <span className="material-symbols-outlined text-3xl">add</span>
            </button>
          </div>

          <NavItem icon="edit_document" label="Registrar" active={isActive('/new-record')} onClick={() => navigate('/new-record')} />
          <NavItem icon="settings" label="Ajustes" active={isActive('/settings')} onClick={() => {}} />
        </div>
      </nav>
      {/* iOS Safe Area Spacer */}
      <div className="md:hidden h-[env(safe-area-inset-bottom)] bg-surface-light dark:bg-surface-dark w-full fixed bottom-0 z-50"></div>
    </div>
  );
};

const NavItem = ({ icon, label, active, onClick }: { icon: string; label: string; active: boolean; onClick: () => void }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 w-16 transition-colors ${active ? 'text-primary' : 'text-slate-400 dark:text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
  >
    <span className={`material-symbols-outlined ${active ? 'filled' : ''}`}>{icon}</span>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

const SidebarItem = ({ icon, label, active, onClick }: { icon: string; label: string; active: boolean; onClick: () => void }) => (
    <button 
      onClick={onClick}
      className={`flex items-center gap-3 w-full p-3 rounded-lg transition-colors ${
          active 
          ? 'bg-primary/10 text-primary font-semibold' 
          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'
      }`}
    >
      <span className={`material-symbols-outlined ${active ? 'filled' : ''}`}>{icon}</span>
      <span className="text-sm">{label}</span>
    </button>
);

const ProtectedRoute = ({ children }: { children: JSX.Element }) => {
    const { isAuthenticated } = useAppContext();
    // For demo purposes, we can skip auth check or uncomment below
    // if (!isAuthenticated) return <Navigate to="/" replace />;
    return <Layout>{children}</Layout>;
}

const App = () => {
  return (
    <AppProvider>
      <HashRouter>
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/dashboard" element={<ProtectedRoute><Dashboard /></ProtectedRoute>} />
          <Route path="/families" element={<ProtectedRoute><FamilyList /></ProtectedRoute>} />
          <Route path="/families/:id" element={<ProtectedRoute><FamilyDetails /></ProtectedRoute>} />
          <Route path="/new-family" element={<ProtectedRoute><NewFamily /></ProtectedRoute>} />
          <Route path="/new-record" element={<ProtectedRoute><NewRecord /></ProtectedRoute>} />
        </Routes>
      </HashRouter>
    </AppProvider>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';

export const Login = () => {
  const navigate = useNavigate();
  const { login } = useAppContext();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    login(); // Set authenticated state
    navigate('/dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-background-light dark:bg-background-dark">
      <div className="w-full max-w-[480px] bg-white dark:bg-surface-dark rounded-2xl shadow-xl p-8 border border-gray-100 dark:border-gray-800">
        <div className="flex flex-col items-center gap-4 mb-8">
          <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/10 text-primary">
            <span className="material-symbols-outlined text-5xl">diversity_3</span>
          </div>
          <div className="text-center">
             <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Gestão Social</h2>
             <p className="text-slate-500 dark:text-slate-400 mt-1">Acesse para gerenciar as famílias</p>
          </div>
        </div>

        <form onSubmit={handleLogin} className="flex flex-col gap-5">
          <div className="flex flex-col gap-2">
            <label className="text-sm font-medium text-slate-700 dark:text-slate-200">E-mail ou Usuário</label>
            <div className="relative">
              <input 
                type="text" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="ex: social@igreja.com"
                className="w-full pl-12 pr-4 h-12 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50 focus:border-primary outline-none transition-all"
              />
              <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">person</span>
            </div>
          </div>

          <div className="flex flex-col gap-2">
            <label className="text-sm font-medium text-slate-700 dark:text-slate-200">Senha</label>
            <div className="relative">
              <input 
                type="password" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full pl-12 pr-4 h-12 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50 focus:border-primary outline-none transition-all"
              />
              <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">lock</span>
            </div>
          </div>

          <button 
            type="submit" 
            className="mt-2 w-full h-12 bg-primary hover:bg-blue-600 text-white font-bold rounded-lg shadow-lg shadow-primary/30 transition-all active:scale-[0.98]"
          >
            Entrar
          </button>
        </form>

        <div className="mt-8 text-center text-sm text-slate-500 dark:text-slate-400">
          <p>Esqueceu a senha? <button className="text-primary hover:underline font-medium">Recuperar</button></p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';
import { Status } from '../types';

export const FamilyList = () => {
  const navigate = useNavigate();
  const { families } = useAppContext();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<Status | 'All'>('All');

  const filteredFamilies = families.filter(family => {
    const matchesSearch = family.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          family.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          family.responsibleName.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === 'All' || family.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-white dark:bg-surface-dark border-b border-gray-200 dark:border-gray-800 px-4 py-3 shadow-sm">
        <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
                <button onClick={() => navigate(-1)} className="p-2 -ml-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-slate-800 dark:text-white">
                    <span className="material-symbols-outlined">arrow_back</span>
                </button>
                <h1 className="text-lg font-bold text-slate-900 dark:text-white">Famílias</h1>
            </div>
            <button 
                onClick={() => navigate('/new-family')}
                className="text-primary font-semibold text-sm hover:bg-primary/5 px-3 py-1.5 rounded-lg transition-colors"
            >
                Adicionar
            </button>
        </div>

        {/* Search & Filter */}
        <div className="flex flex-col gap-3">
            <div className="relative">
                <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar família..."
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-slate-100 dark:bg-background-dark border-none text-slate-900 dark:text-white placeholder:text-slate-400 focus:ring-2 focus:ring-primary/50 outline-none"
                />
            </div>
            <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                <FilterChip label="Todas" active={filterStatus === 'All'} onClick={() => setFilterStatus('All')} />
                <FilterChip label="Críticas" active={filterStatus === Status.Critical} onClick={() => setFilterStatus(Status.Critical)} count={families.filter(f => f.status === Status.Critical).length} />
                <FilterChip label="Ativas" active={filterStatus === Status.Active} onClick={() => setFilterStatus(Status.Active)} />
            </div>
        </div>
      </div>

      {/* List */}
      <div className="flex-1 p-4 flex flex-col gap-3 overflow-y-auto">
        {filteredFamilies.length === 0 ? (
            <div className="flex flex-col items-center justify-center mt-20 text-slate-400">
                <span className="material-symbols-outlined text-6xl mb-4 text-slate-300 dark:text-slate-700">search_off</span>
                <p>Nenhuma família encontrada.</p>
            </div>
        ) : (
            filteredFamilies.map(family => (
                <div 
                    key={family.id}
                    onClick={() => navigate(`/families/${family.id}`)}
                    className="bg-white dark:bg-surface-dark p-4 rounded-xl border border-gray-100 dark:border-gray-800 shadow-sm active:scale-[0.99] transition-transform cursor-pointer flex items-center gap-4"
                >
                    <div className="relative">
                        <img src={family.avatarUrl} alt={family.name} className="size-14 rounded-full object-cover border-2 border-white dark:border-gray-700 shadow-sm" />
                        {family.status === Status.Critical && (
                            <div className="absolute -bottom-1 -right-1 bg-red-500 text-white rounded-full p-0.5 border-2 border-white dark:border-surface-dark">
                                <span className="material-symbols-outlined text-[14px] block">warning</span>
                            </div>
                        )}
                    </div>
                    <div className="flex-1 min-w-0">
                        <div className="flex justify-between items-start">
                             <h3 className="font-bold text-slate-900 dark:text-white truncate">{family.name}</h3>
                             <span className="text-xs text-slate-400 font-mono">{family.code}</span>
                        </div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 truncate">{family.address}</p>
                        <div className="flex items-center gap-2 mt-2">
                             <span className="text-xs bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-2 py-0.5 rounded-full flex items-center gap-1">
                                <span className="material-symbols-outlined text-[12px]">person</span>
                                {family.responsibleName}
                             </span>
                             {family.churchMember && (
                                <span className="text-xs bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 px-2 py-0.5 rounded-full">
                                    Membro
                                </span>
                             )}
                        </div>
                    </div>
                    <span className="material-symbols-outlined text-slate-300 dark:text-slate-600">chevron_right</span>
                </div>
            ))
        )}
      </div>
    </div>
  );
};

const FilterChip = ({ label, active, onClick, count }: { label: string, active: boolean, onClick: () => void, count?: number }) => (
    <button 
        onClick={onClick}
        className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-colors border ${
            active 
            ? 'bg-primary text-white border-primary' 
            : 'bg-white dark:bg-surface-dark text-slate-600 dark:text-slate-300 border-slate-200 dark:border-gray-700 hover:bg-slate-50 dark:hover:bg-gray-800'
        }`}
    >
        {label} {count !== undefined && <span className={`ml-1 text-xs opacity-80 ${active ? 'bg-white/20 px-1.5 rounded-full' : ''}`}>({count})</span>}
    </button>
);

import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';
import { Status } from '../types';

export const FamilyDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { families } = useAppContext();
  const family = families.find(f => f.id === id);
  const [activeTab, setActiveTab] = useState<'info' | 'members' | 'history'>('info');

  if (!family) return <div className="p-4">Família não encontrada</div>;

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-surface-light dark:bg-surface-dark shadow-sm px-4 py-3 flex items-center justify-between border-b border-gray-100 dark:border-gray-800">
        <button onClick={() => navigate(-1)} className="flex size-10 items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-slate-900 dark:text-white">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold text-slate-900 dark:text-white">{family.name}</h1>
        <button className="flex size-10 items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-primary">
          <span className="material-symbols-outlined">edit</span>
        </button>
      </header>

      {/* Profile Header */}
      <div className="bg-surface-light dark:bg-surface-dark pt-6 pb-2 px-4 flex flex-col items-center border-b border-gray-100 dark:border-gray-800">
         <div className="relative mb-3">
            <img src={family.avatarUrl} alt={family.name} className="size-24 rounded-full object-cover border-4 border-slate-50 dark:border-gray-700 shadow-md" />
            <div className={`absolute bottom-0 right-0 size-7 rounded-full border-2 border-white dark:border-surface-dark flex items-center justify-center ${family.status === Status.Critical ? 'bg-red-500' : 'bg-green-500'}`}>
                <span className="material-symbols-outlined text-white text-xs">{family.status === Status.Critical ? 'warning' : 'check'}</span>
            </div>
         </div>
         <h2 className="text-xl font-bold text-slate-900 dark:text-white">{family.name}</h2>
         <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">{family.code}</p>

         <div className="grid grid-cols-3 gap-3 w-full max-w-xs mt-6 mb-4">
             <QuickAction icon="call" label="Ligar" href={`tel:${family.phone}`} />
             <QuickAction icon="chat" label="WhatsApp" color="text-green-600 bg-green-50 dark:bg-green-900/20" />
             <QuickAction icon="map" label="Mapa" color="text-purple-600 bg-purple-50 dark:bg-purple-900/20" />
         </div>
      </div>

      {/* Tabs */}
      <div className="sticky top-[60px] z-30 bg-surface-light dark:bg-surface-dark border-b border-gray-200 dark:border-gray-800 px-4 flex">
        <TabButton label="Dados" active={activeTab === 'info'} onClick={() => setActiveTab('info')} />
        <TabButton label="Membros" active={activeTab === 'members'} onClick={() => setActiveTab('members')} />
        <TabButton label="Histórico" active={activeTab === 'history'} onClick={() => setActiveTab('history')} />
      </div>

      {/* Content */}
      <div className="p-4 flex flex-col gap-4">
        {activeTab === 'info' && (
            <>
                <div className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-800 space-y-4">
                    <h3 className="font-bold text-slate-900 dark:text-white border-b border-gray-100 dark:border-gray-700 pb-2">Situação Atual</h3>
                    <div className="bg-blue-50 dark:bg-blue-900/10 p-3 rounded-lg border border-blue-100 dark:border-blue-900/20">
                        <p className="text-sm text-slate-700 dark:text-slate-300">{family.statusDescription}</p>
                    </div>
                </div>

                <div className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-800 space-y-4">
                    <h3 className="font-bold text-slate-900 dark:text-white border-b border-gray-100 dark:border-gray-700 pb-2">Contato e Endereço</h3>
                    <div className="space-y-4">
                        <div className="flex gap-3">
                            <span className="material-symbols-outlined text-slate-400">location_on</span>
                            <div>
                                <p className="text-sm font-medium text-slate-900 dark:text-white">{family.address}</p>
                                <p className="text-xs text-slate-500">Bairro Central</p>
                            </div>
                        </div>
                        <div className="flex gap-3">
                            <span className="material-symbols-outlined text-slate-400">phone</span>
                            <div>
                                <p className="text-sm font-medium text-slate-900 dark:text-white">{family.phone}</p>
                            </div>
                        </div>
                        <div className="flex gap-3">
                            <span className="material-symbols-outlined text-slate-400">church</span>
                            <div>
                                <p className="text-sm font-medium text-slate-900 dark:text-white">{family.congregation || 'Não informado'}</p>
                                <p className="text-xs text-slate-500">{family.churchMember ? 'Membro' : 'Visitante'}</p>
                            </div>
                        </div>
                    </div>
                </div>
            </>
        )}

        {activeTab === 'members' && (
            <div className="flex flex-col gap-3">
                {family.members.map(member => (
                    <div key={member.id} className="bg-white dark:bg-surface-dark p-3 rounded-xl shadow-sm border border-gray-100 dark:border-gray-800 flex items-center gap-4">
                         <div className="size-10 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-slate-500">
                             <span className="material-symbols-outlined">person</span>
                         </div>
                         <div className="flex-1">
                             <h4 className="font-bold text-slate-900 dark:text-white text-sm">{member.name}</h4>
                             <p className="text-xs text-slate-500 dark:text-slate-400">{member.role} • {member.age} anos</p>
                         </div>
                         <div className="flex gap-1">
                            {member.tags?.map(tag => (
                                <span key={tag} className="text-[10px] bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-2 py-1 rounded-md">{tag}</span>
                            ))}
                         </div>
                    </div>
                ))}
