  isAuthenticated: boolean;
  login: () => void;
  logout: () => void;
  theme: 'light' | 'dark';
  toggleTheme: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

const AppProvider = ({ children }: { children: ReactNode }) => {
  const [families, setFamilies] = useState<Family[]>(MOCK_FAMILIES);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  useEffect(() => {
    // Check system preference or local storage could go here
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        setTheme('dark');
        document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
      setTheme(prev => {
          const newTheme = prev === 'light' ? 'dark' : 'light';
          if (newTheme === 'dark') {
              document.documentElement.classList.add('dark');
          } else {
              document.documentElement.classList.remove('dark');
          }
          return newTheme;
      });
  };

  const addFamily = (family: Family) => {
    setFamilies(prev => [...prev, family]);
  };

  const login = () => setIsAuthenticated(true);
  const logout = () => setIsAuthenticated(false);

  return (
    <AppContext.Provider value={{ families, addFamily, isAuthenticated, login, logout, theme, toggleTheme }}>
      {children}
    </AppContext.Provider>
  );
};

