                            >
                                <span className="material-symbols-outlined mb-1">
                                    {type === AidType.FoodBasket ? 'shopping_basket' : 
                                     type === AidType.Financial ? 'payments' : 
                                     type === AidType.Medicine ? 'medication' : 
                                     type === AidType.Clothes ? 'checkroom' : 
                                     type === AidType.Gas ? 'propane' :
                                     type === AidType.Spiritual ? 'volunteer_activism' :
                                     type === AidType.Other ? 'more_horiz' :
                                     'card_giftcard'}
                                </span>
                                <span className="text-xs font-bold">{type}</span>
                            </button>
                        ))}
                    </div>

                    {/* Custom Input for 'Outros' */}
                    {aidType === AidType.Other && (
                        <div className="animate-in fade-in slide-in-from-top-2 duration-200 pt-1">
                             <label className="text-xs font-medium text-slate-500 ml-1 mb-1 block">Especifique o tipo de ajuda:</label>
                             <input 
                                type="text"
                                value={customAidDetail}
                                onChange={(e) => setCustomAidDetail(e.target.value)}
                                className="w-full h-11 rounded-lg border border-slate-200 dark:border-gray-700 bg-white dark:bg-surface-dark px-4 focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all placeholder:text-slate-400 text-slate-900 dark:text-white"
                                placeholder="Ex: Móveis, Transporte, Pagamento de Luz..."
                                autoFocus
                             />
                        </div>
                    )}
                </div>
            )}

            {/* Details */}
            <div className="space-y-2">
                <label className="text-sm font-bold text-slate-900 dark:text-white ml-1">Observações</label>
                <textarea 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="Descreva detalhes sobre a visita ou itens entregues..."
                    className="w-full min-h-[120px] p-4 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-surface-dark text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-primary/50 resize-none"
                ></textarea>
            </div>

        </div>

        {/* Footer Action */}
        <div className="fixed bottom-0 left-0 right-0 bg-white dark:bg-surface-dark border-t border-gray-200 dark:border-gray-800 p-4 pb-8 z-40 md:pl-64">
            <button 
                onClick={handleSave}
                disabled={!selectedFamilyId || (recordType === 'Aid' && aidType === AidType.Other && !customAidDetail)}
                className="w-full flex items-center justify-center gap-2 bg-primary disabled:bg-slate-300 dark:disabled:bg-slate-700 disabled:cursor-not-allowed hover:bg-yellow-600 text-white font-bold h-12 rounded-xl transition-colors shadow-lg shadow-yellow-500/20"
            >
                <span className="material-symbols-outlined">save</span>
                <span>Salvar Registro</span>
            </button>
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';
import { Status } from '../types';

export const FamilyList = () => {
  const navigate = useNavigate();
  const { families } = useAppContext();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<Status | 'All'>('All');

  // States for Age Filter
  const [showAgeFilter, setShowAgeFilter] = useState(false);
  const [minAge, setMinAge] = useState('');
  const [maxAge, setMaxAge] = useState('');

  const filteredFamilies = families.filter(family => {
    // 1. Text Search
    const matchesSearch = family.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          family.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          family.responsibleName.toLowerCase().includes(searchTerm.toLowerCase());

    // 2. Status Filter
    const matchesStatus = filterStatus === 'All' || family.status === filterStatus;

    // 3. Age/Children Filter
    // Checks if the family has ANY member within the specified range
    let matchesAge = true;
    if (showAgeFilter && (minAge !== '' || maxAge !== '')) {
        const min = minAge !== '' ? parseInt(minAge) : 0;
        const max = maxAge !== '' ? parseInt(maxAge) : 100;

        matchesAge = family.members.some(member => member.age >= min && member.age <= max);
    }

    return matchesSearch && matchesStatus && matchesAge;
  });

  const clearAgeFilter = () => {
      setMinAge('');
      setMaxAge('');
      setShowAgeFilter(false);
  };

  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-white dark:bg-surface-dark border-b border-gray-200 dark:border-gray-800 px-4 py-3 shadow-sm">
        <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
                <button onClick={() => navigate(-1)} className="flex items-center gap-1 p-2 -ml-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 text-slate-800 dark:text-white transition-colors">
                    <span className="material-symbols-outlined">arrow_back</span>
                    <span className="text-sm font-medium">Voltar</span>
                </button>
                <h1 className="text-lg font-bold text-slate-900 dark:text-white">Famílias</h1>
            </div>
            <button 
                onClick={() => navigate('/new-family')}
                className="text-primary font-semibold text-sm hover:bg-primary/5 px-3 py-1.5 rounded-lg transition-colors"
            >
                Adicionar
            </button>
        </div>

        {/* Search & Filter */}
        <div className="flex flex-col gap-3">
            <div className="relative">
                <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar família..."
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-slate-100 dark:bg-background-dark border-none text-slate-900 dark:text-white placeholder:text-slate-400 focus:ring-2 focus:ring-primary/50 outline-none"
                />
            </div>

            <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-1">
                <FilterChip label="Todas" active={filterStatus === 'All'} onClick={() => setFilterStatus('All')} />
                <FilterChip label="Críticas" active={filterStatus === Status.Critical} onClick={() => setFilterStatus(Status.Critical)} count={families.filter(f => f.status === Status.Critical).length} />
                <FilterChip label="Ativas" active={filterStatus === Status.Active} onClick={() => setFilterStatus(Status.Active)} />

                <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>

                <button 
                    onClick={() => setShowAgeFilter(!showAgeFilter)}
                    className={`whitespace-nowrap px-3 py-1.5 rounded-full text-sm font-medium transition-colors border flex items-center gap-1 ${
                        showAgeFilter || minAge || maxAge
                        ? 'bg-primary/10 text-primary border-primary/20' 
                        : 'bg-white dark:bg-surface-dark text-slate-600 dark:text-slate-300 border-slate-200 dark:border-gray-700 hover:bg-slate-50 dark:hover:bg-gray-800'
                    }`}
                >
                    <span className="material-symbols-outlined text-sm">child_care</span>
                    Filhos/Idade
                </button>
            </div>

            {/* Expanded Age Filter */}
            {showAgeFilter && (
                <div className="animate-in fade-in slide-in-from-top-2 duration-200 bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl border border-slate-100 dark:border-slate-700 flex items-center gap-3">
                    <div className="flex items-center gap-2 flex-1">
                        <div className="flex-1">
                            <label className="text-[10px] uppercase font-bold text-slate-400 ml-1">Mín (Anos)</label>
                            <input 
                                type="number" 
                                value={minAge}
                                onChange={(e) => setMinAge(e.target.value)}
                                placeholder="0"
                                className="w-full h-9 rounded-lg border border-slate-200 dark:border-slate-600 px-2 text-sm bg-white dark:bg-surface-dark text-slate-900 dark:text-white focus:ring-1 focus:ring-primary outline-none"
                            />
                        </div>
                        <div className="pt-4 text-slate-400">-</div>
                        <div className="flex-1">
                            <label className="text-[10px] uppercase font-bold text-slate-400 ml-1">Máx (Anos)</label>
                            <input 
                                type="number" 
                                value={maxAge}
                                onChange={(e) => setMaxAge(e.target.value)}
                                placeholder="18"
                                className="w-full h-9 rounded-lg border border-slate-200 dark:border-slate-600 px-2 text-sm bg-white dark:bg-surface-dark text-slate-900 dark:text-white focus:ring-1 focus:ring-primary outline-none"
                            />
                        </div>
                    </div>
                    {(minAge || maxAge) && (
                        <button onClick={clearAgeFilter} className="mt-3 p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors">
                            <span className="material-symbols-outlined text-lg">close</span>
                        </button>
                    )}
                </div>
            )}
        </div>
      </div>

      {/* List */}
      <div className="flex-1 p-4 flex flex-col gap-3 overflow-y-auto">
        {filteredFamilies.length === 0 ? (
            <div className="flex flex-col items-center justify-center mt-20 text-slate-400">
                <span className="material-symbols-outlined text-6xl mb-4 text-slate-300 dark:text-slate-700">search_off</span>
                <p>Nenhuma família encontrada.</p>
                {(minAge || maxAge) && <p className="text-xs mt-2 text-primary">Tente ajustar o filtro de idade.</p>}
            </div>
        ) : (
            filteredFamilies.map(family => (
                <div 
                    key={family.id}
                    onClick={() => navigate(`/families/${family.id}`)}
                    className="bg-white dark:bg-surface-dark p-4 rounded-xl border border-gray-100 dark:border-gray-800 shadow-sm active:scale-[0.99] transition-transform cursor-pointer flex items-center gap-4"
                >
                    <div className="relative">
                        <img src={family.avatarUrl} alt={family.name} className="size-14 rounded-full object-cover border-2 border-white dark:border-gray-700 shadow-sm" />
                        {family.status === Status.Critical && (
                            <div className="absolute -bottom-1 -right-1 bg-red-500 text-white rounded-full p-0.5 border-2 border-white dark:border-surface-dark">
                                <span className="material-symbols-outlined text-[14px] block">warning</span>
                            </div>
                        )}
                    </div>
                    <div className="flex-1 min-w-0">
                        <div className="flex justify-between items-start">
                             <h3 className="font-bold text-slate-900 dark:text-white truncate">{family.name}</h3>
                             <span className="text-xs text-slate-400 font-mono">{family.code}</span>
                        </div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 truncate">{family.address}</p>
                        <div className="flex flex-wrap items-center gap-2 mt-2">
                             <span className="text-xs bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-2 py-0.5 rounded-full flex items-center gap-1">
                                <span className="material-symbols-outlined text-[12px]">person</span>
                                {family.responsibleName}
                             </span>
                             {/* Show child count badge if filter is active or generally informative */}
                             <span className="text-xs bg-slate-50 dark:bg-slate-800/50 text-slate-500 border border-slate-100 dark:border-slate-700 px-2 py-0.5 rounded-full flex items-center gap-1">
                                <span className="material-symbols-outlined text-[12px]">child_care</span>
                                {family.members.filter(m => m.age <= 18).length}
                             </span>
                        </div>
                    </div>
                    <span className="material-symbols-outlined text-slate-300 dark:text-slate-600">chevron_right</span>
                </div>
            ))
        )}
      </div>
    </div>
  );
};

const FilterChip = ({ label, active, onClick, count }: { label: string, active: boolean, onClick: () => void, count?: number }) => (
    <button 
        onClick={onClick}
        className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-colors border ${
            active 
            ? 'bg-primary text-white border-primary' 
            : 'bg-white dark:bg-surface-dark text-slate-600 dark:text-slate-300 border-slate-200 dark:border-gray-700 hover:bg-slate-50 dark:hover:bg-gray-800'
        }`}
    >
        {label} {count !== undefined && <span className={`ml-1 text-xs opacity-80 ${active ? 'bg-white/20 px-1.5 rounded-full' : ''}`}>({count})</span>}
    </button>
);

export enum Status {
  Active = 'Active',
  Critical = 'Critical',
  Archived = 'Archived'
}

export enum AidType {
  FoodBasket = 'Cesta Básica',
  Clothes = 'Roupas',
  Medicine = 'Medicamentos',
  Financial = 'Financeiro',
  Spiritual = 'Apoio Espiritual',
  Gas = 'Gás',
  Other = 'Outros'
}

export interface FamilyMember {
  id: string;
  name: string;
  role: string; // e.g., Pai, Mãe, Filho
  age: number;
  ageType?: 'Years' | 'Months'; // Defaults to Years if undefined
  tags?: string[]; // e.g., 'Estuda', 'Desempregado'
  avatarUrl?: string;
}

export interface HistoryRecord {
  id: string;
  date: string;
  type: 'Visit' | 'Aid' | 'Update';
  title: string;
  description: string;
  responsible: string;
}

export interface Family {
  id: string;
  code: string; // e.g., #FAM-2024-001
  name: string; // Family name usually mostly surname or responsible name
  responsibleName: string;
  avatarUrl: string;
  status: Status;
  statusDescription: string;
  address: string;
  neighborhood?: string;
  phone: string;
  whatsapp?: string;
  members: FamilyMember[];
  history: HistoryRecord[];
  needs?: string[];
  churchMember: boolean;
  congregation?: string;
  income?: string;
  socialClass?: string;
  professionalStatus?: string;
  mainNeed?: string;
  observations?: string;
}

export interface DashboardStats {
  totalFamilies: number;
  criticalFamilies: number;
  monthlyAid: { name: string; value: number; fill: string }[];
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';
import { Status, FamilyMember } from '../types';

export const NewFamily = () => {
  const navigate = useNavigate();
  const { addFamily } = useAppContext();

  // State for the main family data
  const [formData, setFormData] = useState({
      responsibleName: '',
      address: '',
      neighborhood: '',
      phone: '',
      whatsapp: '',
      churchMember: false,
      congregation: '',
      socialClass: '',
      income: '',
      professionalStatus: '',
      mainNeed: '',
      observations: '',
  });

  // State for the list of members being added
  const [members, setMembers] = useState<FamilyMember[]>([]);

  // State for the temporary member form inputs
  const [tempMember, setTempMember] = useState<{
      name: string;
      role: string;
      age: string;
      ageType: 'Years' | 'Months';
      tags: string;
  }>({
      name: '',
      role: '',
      age: '',
      ageType: 'Years',
      tags: ''
  });

  const handleAddMember = (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent form submission

      if (!tempMember.name || !tempMember.role) {
          alert("Nome e Parentesco são obrigatórios para adicionar um membro.");
          return;
      }

      // Validation for months
      if (tempMember.ageType === 'Months' && Number(tempMember.age) > 11) {
          alert("Para bebês, a idade em meses deve ser entre 0 e 11. Para 12 meses ou mais, selecione 'Anos'.");
          return;
      }

      const newMember: FamilyMember = {
          id: Math.random().toString(36).substr(2, 9),
          name: tempMember.name,
          role: tempMember.role,
          age: Number(tempMember.age) || 0,
          ageType: tempMember.ageType,
          tags: tempMember.tags ? tempMember.tags.split(',').map(t => t.trim()).filter(t => t !== '') : []
      };

      setMembers([...members, newMember]);
      setTempMember({ name: '', role: '', age: '', ageType: 'Years', tags: '' }); // Reset fields
  };

  const handleRemoveMember = (id: string) => {
      setMembers(members.filter(m => m.id !== id));
  };

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();

      const newFamily = {
          id: Math.random().toString(),
          code: `#FAM-2024-${Math.floor(Math.random() * 1000).toString().padStart(3, '0')}`,
          name: `Família ${formData.responsibleName.split(' ').pop() || ''}`,
          responsibleName: formData.responsibleName,
          avatarUrl: `https://picsum.photos/seed/${Math.random()}/200/200`,
          status: Status.Active,
          statusDescription: formData.mainNeed || 'Em análise',
          address: formData.address,
          neighborhood: formData.neighborhood,
          phone: formData.phone,
          whatsapp: formData.whatsapp,
          income: formData.income,
          socialClass: formData.socialClass,
          professionalStatus: formData.professionalStatus,
          mainNeed: formData.mainNeed,
          observations: formData.observations,
          members: members, // Include the added members
          history: [],
          churchMember: formData.churchMember,
          congregation: formData.congregation
      };

      addFamily(newFamily);
      navigate('/dashboard');
  };

  const handleCurrencyChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, "");
    value = (Number(value) / 100).toFixed(2).replace(".", ",");
    value = value.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    setFormData({ ...formData, income: value });
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-background-dark">
      {/* Header */}
      <div className="sticky top-0 z-50 flex items-center bg-white dark:bg-surface-dark px-4 py-4 justify-between border-b border-gray-100 dark:border-gray-800 shadow-sm">
        <button onClick={() => navigate(-1)} className="flex items-center gap-1 p-2 -ml-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 text-slate-800 dark:text-white transition-colors">
            <span className="material-symbols-outlined">arrow_back</span>
            <span className="text-sm font-medium">Voltar</span>
        </button>
        <h2 className="text-lg font-bold text-slate-900 dark:text-white">Novo Cadastro</h2>
