interface QuickActionProps {
    icon: string;
    label: string;
    href?: string;
    color?: string;
    target?: string;
}

const QuickAction = ({ icon, label, href, color = 'text-primary bg-primary/10', target }: QuickActionProps) => (
    <a 
        href={href} 
        target={target}
        rel={target === '_blank' ? "noopener noreferrer" : undefined}
        className={`flex flex-col items-center gap-2 p-2 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 transition cursor-pointer ${!href ? 'opacity-50 pointer-events-none grayscale' : ''}`}
    >
        <div className={`size-10 rounded-full flex items-center justify-center ${color}`}>
            <span className="material-symbols-outlined">{icon}</span>
        </div>
        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">{label}</span>
    </a>
);

const TabButton = ({ label, active, onClick }: { label: string, active: boolean, onClick: () => void }) => (
    <button 
        onClick={onClick}
        className={`flex-1 pb-3 pt-4 text-sm font-bold tracking-wide border-b-[3px] transition-colors ${
            active 
            ? 'border-primary text-slate-900 dark:text-white' 
            : 'border-transparent text-slate-400 dark:text-slate-500 hover:text-primary'
        }`}
    >
        {label}
    </button>
);

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../App';
import { Status, FamilyMember } from '../types';

export const NewFamily = () => {
  const navigate = useNavigate();
  const { addFamily } = useAppContext();

  // State for the main family data
  const [formData, setFormData] = useState({
      responsibleName: '',
      address: '',
      neighborhood: '',
      phone: '',
      whatsapp: '',
      churchMember: false,
      congregation: '',
      socialClass: '',
      income: '',
      professionalStatus: '',
      mainNeed: '',
      observations: '',
  });

  // State for the list of members being added
  const [members, setMembers] = useState<FamilyMember[]>([]);

  // State for the temporary member form inputs
  const [tempMember, setTempMember] = useState<{
      name: string;
      role: string;
      age: string;
      ageType: 'Years' | 'Months';
      tags: string;
  }>({
      name: '',
      role: '',
      age: '',
      ageType: 'Years',
      tags: ''
  });

  const handleAddMember = (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent form submission

      if (!tempMember.name || !tempMember.role) {
          alert("Nome e Parentesco são obrigatórios para adicionar um membro.");
          return;
      }

      // Validation for months
      if (tempMember.ageType === 'Months' && Number(tempMember.age) > 11) {
          alert("Para bebês, a idade em meses deve ser entre 0 e 11. Para 12 meses ou mais, selecione 'Anos'.");
          return;
      }

      const newMember: FamilyMember = {
          id: Math.random().toString(36).substr(2, 9),
          name: tempMember.name,
          role: tempMember.role,
          age: Number(tempMember.age) || 0,
          ageType: tempMember.ageType,
          tags: tempMember.tags ? tempMember.tags.split(',').map(t => t.trim()).filter(t => t !== '') : []
      };

      setMembers([...members, newMember]);
      setTempMember({ name: '', role: '', age: '', ageType: 'Years', tags: '' }); // Reset fields
  };

  const handleRemoveMember = (id: string) => {
      setMembers(members.filter(m => m.id !== id));
