    let value = e.target.value.replace(/\D/g, "");
    value = (Number(value) / 100).toFixed(2).replace(".", ",");
    value = value.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    setFormData({ ...formData, income: value });
  };

