import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { useAppContext } from '../constants';
import { AidType } from '../types';

export const Reports = () => {
  const navigate = useNavigate();
  const { families } = useAppContext();

  // --- State for Filters ---
  const [selectedMonth, setSelectedMonth] = useState<string>(String(new Date().getMonth())); // 0-11
  const [selectedYear, setSelectedYear] = useState<string>('2023'); // Default to mock data year usually
  const [selectedType, setSelectedType] = useState<string>('All');

  // --- Data Processing ---

  // 1. Flatten all aid records from all families into a single list
  const allAidRecords = useMemo(() => {
    return families.flatMap(family => 
        family.history
            .filter(record => record.type === 'Aid')
            .map(record => ({
                ...record,
                familyId: family.id,
                familyName: family.name,
                familyAvatar: family.avatarUrl,
                familyCode: family.code
            }))
    );
  }, [families]);

  // 2. Filter records based on selection
  const filteredRecords = useMemo(() => {
    return allAidRecords.filter(record => {
        const recordDate = new Date(record.date); // Assuming YYYY-MM-DD format

        // Fix timezone offset issue for simple date parsing if necessary, 
        // but simple getMonth() usually works if string is ISO.
        // Safer to parse parts manually for YYYY-MM-DD strings to avoid timezone shifts
        const [rYear, rMonth] = record.date.split('-').map(Number);

        const matchesMonth = (rMonth - 1) === Number(selectedMonth);
        const matchesYear = rYear === Number(selectedYear);
        const matchesType = selectedType === 'All' || record.title === selectedType || (selectedType === 'Outros' && !Object.values(AidType).includes(record.title as AidType));

        return matchesMonth && matchesYear && matchesType;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [allAidRecords, selectedMonth, selectedYear, selectedType]);

  // 3. Calculate Stats based on filtered records
  const totalAidCount = filteredRecords.length;

  // Unique families helped in this period
  const uniqueFamiliesHelped = new Set(filteredRecords.map(r => r.familyId)).size;

  // Group by Type for Chart
  const typeDistribution = useMemo(() => {
      const counts: Record<string, number> = {};
      filteredRecords.forEach(r => {
          counts[r.title] = (counts[r.title] || 0) + 1;
      });
      return Object.entries(counts).map(([name, value], index) => ({
          name, 
          value,
          fill: ['#EAB308', '#F97316', '#14B8A6', '#EF4444', '#A855F7'][index % 5]
      }));
  }, [filteredRecords]);

  const months = [
      "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
      "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"
  ];

  const years = ['2022', '2023', '2024', '2025'];

  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark overflow-y-auto">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-white dark:bg-surface-dark border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center gap-3 shadow-sm">
        <button onClick={() => navigate(-1)} className="flex items-center gap-1 p-2 -ml-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 text-slate-800 dark:text-white transition-colors">
            <span className="material-symbols-outlined">arrow_back</span>
            <span className="text-sm font-medium">Voltar</span>
        </button>
        <h1 className="text-lg font-bold text-slate-900 dark:text-white">Relatório de Atendimentos</h1>
      </div>

      <div className="p-4 space-y-6 max-w-5xl mx-auto w-full pb-24">

        {/* Filters Bar */}
        <section className="bg-white dark:bg-surface-dark p-4 rounded-xl border border-gray-100 dark:border-gray-800 shadow-sm flex flex-col md:flex-row gap-4 items-center">
            <div className="flex items-center gap-2 w-full md:w-auto">
                <span className="material-symbols-outlined text-slate-400">filter_list</span>
                <span className="text-sm font-bold text-slate-700 dark:text-slate-300 whitespace-nowrap">Filtrar por:</span>
            </div>

            <div className="grid grid-cols-3 gap-2 w-full">
                <select 
                    value={selectedMonth} 
                    onChange={(e) => setSelectedMonth(e.target.value)}
                    className="h-10 rounded-lg border border-slate-200 dark:border-gray-700 bg-slate-50 dark:bg-background-dark px-2 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50 outline-none"
                >
                    {months.map((m, i) => <option key={i} value={i}>{m}</option>)}
                </select>

                <select 
                    value={selectedYear} 
                    onChange={(e) => setSelectedYear(e.target.value)}
                    className="h-10 rounded-lg border border-slate-200 dark:border-gray-700 bg-slate-50 dark:bg-background-dark px-2 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50 outline-none"
                >
                    {years.map(y => <option key={y} value={y}>{y}</option>)}
                </select>

                <select 
                    value={selectedType} 
                    onChange={(e) => setSelectedType(e.target.value)}
                    className="h-10 rounded-lg border border-slate-200 dark:border-gray-700 bg-slate-50 dark:bg-background-dark px-2 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50 outline-none"
                >
                    <option value="All">Todos Tipos</option>
                    {Object.values(AidType).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
            </div>
        </section>

        {/* Dynamic Summary Stats */}
        <section className="grid grid-cols-2 md:grid-cols-3 gap-3">
            <StatCard 
                label="Famílias Atendidas" 
                value={uniqueFamiliesHelped} 
                icon="diversity_1" 
                color="text-primary bg-yellow-50 dark:bg-yellow-900/20" 
            />
            <StatCard 
                label="Total de Doações" 
                value={totalAidCount} 
                icon="inventory_2" 
                color="text-orange-500 bg-orange-50 dark:bg-orange-900/20" 
            />
            <StatCard 
                label="Tipo + Comum" 
                value={typeDistribution.length > 0 ? typeDistribution.sort((a,b) => b.value - a.value)[0].name : '-'} 
                icon="trending_up" 
                color="text-green-500 bg-green-50 dark:bg-green-900/20" 
                isText
            />
        </section>

        {filteredRecords.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                <span className="material-symbols-outlined text-5xl mb-2 opacity-50">event_busy</span>
                <p>Nenhum registro encontrado para este período.</p>
            </div>
        ) : (
            <>
                {/* Detailed Table / List */}
                <section className="bg-white dark:bg-surface-dark rounded-xl border border-gray-100 dark:border-gray-800 shadow-sm overflow-hidden">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center">
                        <h3 className="font-bold text-slate-900 dark:text-white">Detalhes dos Atendimentos</h3>
                        <span className="text-xs font-medium bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded text-slate-600 dark:text-slate-400">
                            {filteredRecords.length} registros
                        </span>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-500 font-medium">
                                <tr>
                                    <th className="px-4 py-3">Família</th>
                                    <th className="px-4 py-3">Tipo de Ajuda</th>
                                    <th className="px-4 py-3 hidden sm:table-cell">Data</th>
                                    <th className="px-4 py-3 hidden md:table-cell">Responsável</th>
                                    <th className="px-4 py-3"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
                                {filteredRecords.map((record) => (
                                    <tr key={record.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                        <td className="px-4 py-3">
                                            <div className="flex items-center gap-3">
                                                <img src={record.familyAvatar} alt="" className="size-8 rounded-full object-cover" />
                                                <div>
                                                    <p className="font-bold text-slate-900 dark:text-white text-xs sm:text-sm">{record.familyName}</p>
                                                    <p className="text-[10px] text-slate-500 sm:hidden">{record.date.split('-').reverse().join('/')}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3">
                                            <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                                                record.title === AidType.FoodBasket ? 'bg-orange-50 dark:bg-orange-900/20 text-orange-600 border-orange-100 dark:border-orange-900/30' :
                                                record.title === AidType.Medicine ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-600 border-teal-100 dark:border-teal-900/30' :
                                                'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-gray-700'
                                            }`}>
                                                {record.title}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3 text-slate-600 dark:text-slate-400 hidden sm:table-cell">
                                            {record.date.split('-').reverse().join('/')}
                                        </td>
                                        <td className="px-4 py-3 text-slate-600 dark:text-slate-400 hidden md:table-cell">
                                            {record.responsible}
                                        </td>
                                        <td className="px-4 py-3 text-right">
                                            <button 
                                                onClick={() => navigate(`/families/${record.familyId}`)}
                                                className="text-primary hover:text-yellow-600 p-1"
                                                title="Ver Família"
                                            >
                                                <span className="material-symbols-outlined text-lg">visibility</span>
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </section>

                {/* Distribution Chart (Only shows if data exists) */}
                {typeDistribution.length > 0 && (
                    <section className="bg-white dark:bg-surface-dark p-5 rounded-xl border border-gray-100 dark:border-gray-800 shadow-sm">
                        <h3 className="font-bold text-slate-900 dark:text-white mb-4">Distribuição Visual ({months[Number(selectedMonth)]})</h3>
                        <div className="h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart layout="vertical" data={typeDistribution} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                                    <XAxis type="number" hide />
                                    <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 11, fill: '#94a3b8'}} axisLine={false} tickLine={false} />
                                    <Tooltip 
                                        cursor={{fill: 'transparent'}}
                                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', backgroundColor: 'var(--bg-surface-light)' }} 
                                    />
                                    <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={24}>
                                        {typeDistribution.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.fill} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </section>
                )}
            </>
        )}
      </div>
    </div>
  );
