            className="relative size-10 rounded-full overflow-hidden border-2 border-white dark:border-gray-700 shadow-sm"
        >
            <img alt="User" className="size-full object-cover" src="https://ui-avatars.com/api/?name=Admin&background=EAB308&color=fff" />
        </button>
      </header>

      {/* Search */}
      <div className="relative w-full">
        <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">search</span>
