// --- Helper Functions for Mapping ---
const mapFamilyFromDB = (row: any): Family => ({
  id: row.id,
  code: row.code,
  name: row.name,
  responsibleName: row.responsible_name,
  avatarUrl: row.avatar_url,
  status: row.status as Status,
  statusDescription: row.status_description,
  address: row.address,
  neighborhood: row.neighborhood,
  phone: row.phone,
  whatsapp: row.whatsapp,
  churchMember: row.church_member,
  congregation: row.congregation,
  income: row.income,
  socialClass: row.social_class,
  professionalStatus: row.professional_status,
  mainNeed: row.main_need,
  observations: row.observations,
  members: Array.isArray(row.members) ? row.members : [],
  history: Array.isArray(row.history) ? row.history : []
});

const mapFamilyToDB = (family: Family) => ({
  id: family.id,
  code: family.code,
  name: family.name,
  responsible_name: family.responsibleName,
  avatar_url: family.avatarUrl,
  status: family.status,
  status_description: family.statusDescription,
  address: family.address,
  neighborhood: family.neighborhood,
  phone: family.phone,
  whatsapp: family.whatsapp,
  church_member: family.churchMember,
  congregation: family.congregation,
  income: family.income,
  social_class: family.socialClass,
  professional_status: family.professionalStatus,
  main_need: family.mainNeed,
  observations: family.observations,
  members: family.members,
  history: family.history
});

const AppProvider = ({ children }: { children?: ReactNode }) => {
  const [families, setFamilies] = useState<Family[]>([]);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [loading, setLoading] = useState(true);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // Initial Fetch from Supabase
  useEffect(() => {
    const fetchFamilies = async () => {
        try {
            // Fetch data without ordering first to avoid potential schema issues
            const { data, error } = await supabase.from('families').select('*');

            if (error) {
                // Check specifically for table missing error (Postgres code 42P01 or generic message)
                const errorMsg = error.message || JSON.stringify(error);

                if (errorMsg.includes('does not exist') || errorMsg.includes('Could not find the table') || error.code === '42P01') {
                    console.warn('⚠️ TABELA "families" NÃO ENCONTRADA NO SUPABASE.');
                    console.info('Por favor, rode o seguinte SQL no editor do Supabase para criar a tabela:');
                    console.log(`
create table families (
  id text primary key,
  code text,
  name text,
  responsible_name text,
  avatar_url text,
  status text,
  status_description text,
  address text,
  neighborhood text,
  phone text,
  whatsapp text,
  church_member boolean,
  congregation text,
  income text,
  social_class text,
  professional_status text,
  main_need text,
  observations text,
  members jsonb default '[]'::jsonb,
  history jsonb default '[]'::jsonb,
  created_at timestamp with time zone default timezone('utc'::text, now())
);
                    `);
                    setIsOfflineMode(true);
                    return;
                }

                console.error('Error fetching families:', errorMsg);
                return;
            }

            if (data) {
                // Client-side sorting by created_at equivalent
                const sorted = (row: any) => row.created_at ? new Date(row.created_at).getTime() : 0;
                data.sort((a: any, b: any) => sorted(b) - sorted(a));

                setFamilies(data.map(mapFamilyFromDB));
            }
        } catch (err) {
            console.error('Unexpected error during fetch:', err);
        } finally {
            setLoading(false);
        }
    };

    fetchFamilies();

    // Check system preference
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        setTheme('dark');
        document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
      setTheme(prev => {
          const newTheme = prev === 'light' ? 'dark' : 'light';
          if (newTheme === 'dark') {
              document.documentElement.classList.add('dark');
          } else {
              document.documentElement.classList.remove('dark');
          }
          return newTheme;
      });
  };

  const addFamily = async (family: Family) => {
    // Optimistic Update
    setFamilies(prev => [family, ...prev]);

    if (isOfflineMode) {
        console.warn('Modo Offline: Dados salvos apenas localmente.');
        return;
    }

    // DB Insert
    try {
        const { error } = await supabase.from('families').insert([mapFamilyToDB(family)]);
        if (error) {
            console.error('Error adding family to DB:', error.message || error);
            alert('Erro ao salvar no banco. Verifique o console.');
        }
    } catch (e) {
        console.error('Exception adding family:', e);
    }
  };

  const removeFamily = async (id: string) => {
    // Optimistic Update
    setFamilies(prev => prev.filter(family => family.id !== id));

    if (isOfflineMode) return;

    // DB Delete
    try {
        const { error } = await supabase.from('families').delete().eq('id', id);
        if (error) {
            console.error('Error removing family from DB:', error.message || error);
        }
    } catch (e) {
        console.error('Exception removing family:', e);
    }
  };

  const addHistoryRecord = async (familyId: string, record: HistoryRecord) => {
    // Find current family state
    const family = families.find(f => f.id === familyId);
    if (!family) return;

    const newHistory = [record, ...family.history];

    // Optimistic Update
    setFamilies(prev => prev.map(f => {
        if (f.id === familyId) {
            return { ...f, history: newHistory };
        }
        return f;
    }));

    if (isOfflineMode) return;

    // DB Update
    try {
        const { error } = await supabase
            .from('families')
            .update({ history: newHistory })
            .eq('id', familyId);

        if (error) {
            console.error('Error updating history in DB:', error.message || error);
            alert('Erro ao salvar registro no banco de dados.');
        }
    } catch (e) {
        console.error('Exception updating history:', e);
    }
  };

  const login = () => setIsAuthenticated(true);
  const logout = () => setIsAuthenticated(false);

  return (
    <AppContext.Provider value={{ families, addFamily, removeFamily, addHistoryRecord, isAuthenticated, login, logout, theme, toggleTheme }}>
      {children}
      {isOfflineMode && (
          <div className="fixed bottom-4 right-4 bg-orange-100 text-orange-800 px-4 py-2 rounded-lg border border-orange-200 shadow-lg z-[100] text-xs font-bold flex items-center gap-2">
            <span className="material-symbols-outlined text-sm">wifi_off</span>
            Modo Offline (Tabela ausente)
          </div>
      )}
    </AppContext.Provider>
  );
};

