        </p>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { AID_STATS_COLORS, useAppContext } from '../constants';
import { AidType } from '../types';

export const Dashboard = () => {
  const navigate = useNavigate();
  const { families } = useAppContext();

  const totalFamilies = families.length;
  const criticalCount = families.filter(f => f.status === 'Critical').length;

  // Calculate Chart Data Dynamically
  const aidStats = useMemo(() => {
      // Initialize counts for all standard types so they appear in the chart even if 0
      const counts: Record<string, number> = {
          [AidType.FoodBasket]: 0,
          [AidType.Clothes]: 0,
          [AidType.Medicine]: 0,
          [AidType.Gas]: 0,
          [AidType.Financial]: 0,
          [AidType.Spiritual]: 0,
      };

      // Count all aids from all families
      families.forEach(family => {
          family.history.forEach(record => {
              if (record.type === 'Aid') {
                  const title = record.title;
                  // Increment existing or initialize new key for custom types
                  if (counts[title] !== undefined) {
                      counts[title]++;
                  } else {
                      counts[title] = 1;
                  }
              }
          });
      });

      // Filter out types with 0 count ONLY if they are not standard types? 
      // Or keep them to show empty state? Let's keep standard types even if 0 for consistency,
      // and keep custom types only if > 0.

      return Object.keys(counts)
          .filter(key => {
             // Optional: Filter out 0 values if you want a cleaner chart, 
             // but usually showing 0 for main categories is good.
             // Let's keep all keys present in 'counts'.
             return true; 
          })
          .map(key => {
              // Determine color
              // Check if key is a known AidType
              const isStandard = Object.values(AidType).includes(key as AidType);
              let color = isStandard ? AID_STATS_COLORS[key as AidType] : undefined;

              // Fallback color for custom types (grouped under 'Other' color or generic)
              if (!color) {
                  color = AID_STATS_COLORS[AidType.Other] || '#cbd5e1';
              }

              return {
                  name: key,
                  value: counts[key],
                  fill: color
              };
          })
          .sort((a, b) => b.value - a.value); // Sort by highest count
  }, [families]);

  return (
    <div className="flex flex-col gap-6 p-4 max-w-4xl mx-auto w-full">
      {/* Header */}
      <header className="flex items-center justify-between">
        <div className="flex items-center gap-3">
            <div className="size-10 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-2xl">church</span>
            </div>
            <div>
                <h1 className="text-lg font-bold leading-tight dark:text-white">Visão Geral</h1>
                <p className="text-xs text-slate-500 dark:text-slate-400 font-medium">Assistência Social</p>
            </div>
        </div>
        <button 
            onClick={() => navigate('/settings')}
            aria-label="Perfil" 
            className="relative size-10 rounded-full overflow-hidden border-2 border-white dark:border-gray-700 shadow-sm"
        >
            <img alt="User" className="size-full object-cover" src="https://ui-avatars.com/api/?name=Admin&background=EAB308&color=fff" />
        </button>
      </header>

      {/* Search */}
      <div className="relative w-full">
        <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">search</span>
        <input 
          onClick={() => navigate('/families')}
          readOnly
          className="block w-full pl-10 pr-3 py-3 rounded-xl border-none bg-white dark:bg-surface-dark text-slate-900 dark:text-white shadow-sm ring-1 ring-slate-200 dark:ring-gray-800 placeholder:text-slate-400 cursor-pointer hover:ring-primary/50 transition-all" 
          placeholder="Buscar família por nome ou código..." 
        />
      </div>

      {/* Stats Cards */}
      <section className="grid grid-cols-2 gap-4">
        <div className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm border border-slate-100 dark:border-gray-800 relative overflow-hidden group">
            <div className="absolute right-[-10px] top-[-10px] size-16 bg-primary/5 rounded-full group-hover:scale-110 transition-transform duration-500"></div>
            <div className="relative z-10 flex items-center gap-2 mb-2">
                <span className="material-symbols-outlined text-primary text-[28px]">groups</span>
            </div>
            <div className="relative z-10">
                <p className="text-slate-500 dark:text-slate-400 text-xs font-medium uppercase tracking-wide">Total de Famílias</p>
                <div className="flex items-baseline gap-2">
                    <h3 className="text-3xl font-bold text-slate-900 dark:text-white">{totalFamilies}</h3>
                </div>
            </div>
        </div>

        <div className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm border border-slate-100 dark:border-gray-800 relative overflow-hidden group">
            <div className="absolute right-[-10px] top-[-10px] size-16 bg-red-50 dark:bg-red-900/10 rounded-full group-hover:scale-110 transition-transform duration-500"></div>
            <div className="relative z-10 flex items-center gap-2 mb-2">
                <span className="material-symbols-outlined text-red-500 text-[28px]">warning</span>
            </div>
            <div className="relative z-10">
                <p className="text-slate-500 dark:text-slate-400 text-xs font-medium uppercase tracking-wide">Situação Crítica</p>
                <div className="flex items-baseline gap-2">
                    <h3 className="text-3xl font-bold text-slate-900 dark:text-white">{criticalCount}</h3>
                </div>
            </div>
        </div>
      </section>

      {/* Quick Actions */}
      <section>
        <h2 className="text-lg font-bold mb-3 px-1 text-slate-900 dark:text-white">Ações Rápidas</h2>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <ActionCard 
                icon="person_add" 
                title="Cadastrar" 
                subtitle="Nova Família" 
                colorClass="bg-primary text-white" 
                iconBgClass="bg-white/20"
                onClick={() => navigate('/new-family')}
                hasArrow
            />
            <ActionCard 
                icon="edit_document" 
                title="Atendimento" 
                subtitle="Registrar visita/ajuda" 
                colorClass="bg-white dark:bg-surface-dark text-slate-900 dark:text-white border border-slate-100 dark:border-gray-800" 
                iconBgClass="bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400"
                onClick={() => navigate('/new-record')}
            />
            <ActionCard 
                icon="monitoring" 
                title="Relatórios" 
                subtitle="Ver estatísticas" 
                colorClass="bg-white dark:bg-surface-dark text-slate-900 dark:text-white border border-slate-100 dark:border-gray-800" 
                iconBgClass="bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400"
                onClick={() => navigate('/reports')}
            />
        </div>
      </section>

      {/* Chart Section */}
      <section>
        <div className="flex items-center justify-between mb-3 px-1">
            <h2 className="text-lg font-bold text-slate-900 dark:text-white">Distribuição de Ajuda (Total)</h2>
        </div>

        {/* Empty State for Chart */}
        {aidStats.every(s => s.value === 0) ? (
            <div className="bg-white dark:bg-surface-dark rounded-xl p-8 shadow-sm border border-slate-100 dark:border-gray-800 flex flex-col items-center justify-center text-center">
                 <div className="size-12 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center mb-3">
                    <span className="material-symbols-outlined text-slate-400">bar_chart</span>
                 </div>
                 <p className="text-slate-900 dark:text-white font-medium">Sem dados ainda</p>
                 <p className="text-sm text-slate-500">Cadastre atendimentos para ver o gráfico.</p>
            </div>
        ) : (
            <div className="bg-white dark:bg-surface-dark rounded-xl p-5 shadow-sm border border-slate-100 dark:border-gray-800 h-auto min-h-[256px]">
                 <ResponsiveContainer width="100%" height={Math.max(250, aidStats.length * 40)}>
                    <BarChart layout="vertical" data={aidStats} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                            dataKey="name" 
                            type="category" 
                            width={110} 
                            tick={{fontSize: 11, fill: '#64748b', fontWeight: 500}} 
                            axisLine={false} 
                            tickLine={false} 
                        />
                        <Tooltip 
                            cursor={{fill: 'transparent'}}
                            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} 
                        />
                        <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={20}>
                            {aidStats.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.fill} />
                            ))}
                        </Bar>
                    </BarChart>
                 </ResponsiveContainer>
            </div>
        )}
      </section>
    </div>
  );
};

