export const Financial = () => {
  const { transactions, addTransaction, removeTransaction } = useAppContext();
  const [showAddModal, setShowAddModal] = useState(false);
  const [filterType, setFilterType] = useState<'All' | TransactionType>('All');

  // Form State
  const [formData, setFormData] = useState({
    type: TransactionType.Income,
    category: 'Dízimos',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    description: ''
  });

  const stats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthlyTransactions = transactions.filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const income = monthlyTransactions.filter(t => t.type === TransactionType.Income).reduce((acc, t) => acc + t.amount, 0);
    const expense = monthlyTransactions.filter(t => t.type === TransactionType.Expense).reduce((acc, t) => acc + t.amount, 0);
    const totalBalance = transactions.reduce((acc, t) => t.type === TransactionType.Income ? acc + t.amount : acc - t.amount, 0);

    return { income, expense, totalBalance };
  }, [transactions]);

  const filteredTransactions = transactions.filter(t => filterType === 'All' || t.type === filterType);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = Number(formData.amount.replace(',', '.'));
    if (isNaN(amount) || amount <= 0) return alert('Insira um valor válido');

    const newTransaction: Transaction = {
        id: crypto.randomUUID(),
        date: formData.date,
        type: formData.type,
        category: formData.category,
        amount: amount,
        description: formData.description,
        responsible: 'Administrador'
    };

    await addTransaction(newTransaction);
    setShowAddModal(false);
    setFormData({ ...formData, amount: '', description: '' });
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-background-dark overflow-y-auto">
      <header className="sticky top-0 z-20 bg-white dark:bg-surface-dark border-b border-gray-200 dark:border-gray-800 px-4 py-4 flex items-center justify-between shadow-sm">
        <h1 className="text-xl font-bold text-slate-900 dark:text-white">Fluxo de Caixa</h1>
        <button 
            onClick={() => setShowAddModal(true)}
            className="bg-primary hover:bg-yellow-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-all shadow-md active:scale-95"
        >
            <span className="material-symbols-outlined">add_card</span>
            Novo Lançamento
        </button>
      </header>

      <div className="p-4 space-y-6 max-w-4xl mx-auto w-full pb-32">
        {/* Stats Grid */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <SummaryCard label="Saldo Geral" value={stats.totalBalance} color="text-slate-900 dark:text-white" icon="account_balance" />
            <SummaryCard label="Entradas (Mês)" value={stats.income} color="text-green-600" icon="trending_up" />
            <SummaryCard label="Saídas (Mês)" value={stats.expense} color="text-red-500" icon="trending_down" />
        </section>

        {/* Filters */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar py-2">
            <button onClick={() => setFilterType('All')} className={`px-4 py-1.5 rounded-full text-sm font-medium border whitespace-nowrap ${filterType === 'All' ? 'bg-primary text-white border-primary' : 'bg-white dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-slate-500'}`}>Tudo</button>
            <button onClick={() => setFilterType(TransactionType.Income)} className={`px-4 py-1.5 rounded-full text-sm font-medium border whitespace-nowrap ${filterType === TransactionType.Income ? 'bg-green-600 text-white border-green-600' : 'bg-white dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-slate-500'}`}>Entradas</button>
            <button onClick={() => setFilterType(TransactionType.Expense)} className={`px-4 py-1.5 rounded-full text-sm font-medium border whitespace-nowrap ${filterType === TransactionType.Expense ? 'bg-red-500 text-white border-red-500' : 'bg-white dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-slate-500'}`}>Saídas</button>
        </div>

