// --- Mappers ---
const mapFamilyFromDB = (row: any): Family => ({
  id: row.id,
  code: row.code,
  name: row.name,
  responsibleName: row.responsible_name,
  avatarUrl: row.avatar_url,
  status: row.status as Status,
  statusDescription: row.status_description,
  address: row.address,
  neighborhood: row.neighborhood,
  phone: row.phone,
  whatsapp: row.whatsapp,
  churchMember: row.church_member,
  congregation: row.congregation,
  income: row.income,
  socialClass: row.social_class,
  professionalStatus: row.professional_status,
  mainNeed: row.main_need,
  observations: row.observations,
  members: Array.isArray(row.members) ? row.members : [],
  history: Array.isArray(row.history) ? row.history : []
});

const mapTransactionFromDB = (row: any): Transaction => ({
  id: row.id,
  date: row.date,
  type: row.type as TransactionType,
  category: row.category,
  amount: Number(row.amount),
  description: row.description,
  responsible: row.responsible
});

const AppProvider = ({ children }: { children?: ReactNode }) => {
  const [families, setFamilies] = useState<Family[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
      try {
          const [familiesRes, transactionsRes] = await Promise.all([
              supabase.from('families').select('*'),
              supabase.from('financial_records').select('*').order('date', { ascending: false })
          ]);

          if (!familiesRes.error && familiesRes.data) {
              setFamilies(familiesRes.data.map(mapFamilyFromDB));
          }

          if (!transactionsRes.error && transactionsRes.data) {
              setTransactions(transactionsRes.data.map(mapTransactionFromDB));
          }
      } catch (err) {
          console.error('Fetch error:', err);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
        setIsAuthenticated(!!session);
        if (session) fetchData();
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
        setIsAuthenticated(!!session);
        if (session) fetchData();
    });

    return () => subscription.unsubscribe();
  }, []);

  const addTransaction = async (transaction: Transaction) => {
    // Optimistic Update
    setTransactions(prev => [transaction, ...prev]);

    const { error } = await supabase.from('financial_records').insert([{
        id: transaction.id,
        date: transaction.date,
        type: transaction.type,
        category: transaction.category,
        amount: transaction.amount,
        description: transaction.description,
        responsible: transaction.responsible
    }]);

    if (error) {
        setTransactions(prev => prev.filter(t => t.id !== transaction.id));
        console.error('Supabase Error:', error);
        alert('Erro ao salvar no banco: ' + error.message);
    }
  };

  const removeTransaction = async (id: string) => {
    const backup = transactions.find(t => t.id === id);
    setTransactions(prev => prev.filter(t => t.id !== id));
    const { error } = await supabase.from('financial_records').delete().eq('id', id);
    if (error && backup) {
        setTransactions(prev => [backup, ...prev]);
        alert('Erro ao remover transação');
    }
  };

  const addFamily = async (family: Family) => {
    setFamilies(prev => [family, ...prev]);
    const { error } = await supabase.from('families').insert([{
        id: family.id,
        code: family.code,
        name: family.name,
        responsible_name: family.responsibleName,
        status: family.status,
        address: family.address,
        phone: family.phone,
        members: family.members,
        history: family.history
    }]);
    if (error) setFamilies(prev => prev.filter(f => f.id !== family.id));
  };

  const addHistoryRecord = async (familyId: string, record: HistoryRecord) => {
    const family = families.find(f => f.id === familyId);
    if (!family) return;
    const newHistory = [record, ...family.history];
    setFamilies(prev => prev.map(f => f.id === familyId ? { ...f, history: newHistory } : f));
    await supabase.from('families').update({ history: newHistory }).eq('id', familyId);
  };

  const toggleTheme = () => {
    setTheme(prev => {
      const next = prev === 'light' ? 'dark' : 'light';
      document.documentElement.classList.toggle('dark', next === 'dark');
      return next;
    });
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setFamilies([]);
    setTransactions([]);
  };

  return (
    <AppContext.Provider value={{ 
        families, transactions, addFamily, removeFamily: () => {}, 
        addHistoryRecord, addTransaction, removeTransaction,
        isAuthenticated, login: () => {}, logout, theme, toggleTheme 
    }}>
      {children}
    </AppContext.Provider>
  );
};

